from pathlib import Path

from repo_ops_py_pip_tools.pip_tools import uv_compile_command

HEADER = (
    "# This file was autogenerated by uv via the following command:\n"
    "#    uv pip compile --generate-hashes --python-version 3.12 "
    "--python-platform x86_64-manylinux_2_28 --torch-backend rocm7.2 "
    "requirements.in -o requirements.txt\n"
    "foo==1.0 \\\n    --hash=sha256:abc\n"
)


def test_recorded_flags_are_rerun_with_upgrade(tmp_path: Path) -> None:
    txt = tmp_path / "requirements.txt"
    txt.write_text(HEADER)

    cmd = uv_compile_command(txt, tmp_path / "requirements.in", str(txt), upgrade=True)

    assert cmd[:3] == ["uv", "pip", "compile"]
    for flag in ("--generate-hashes", "--python-version", "3.12", "--torch-backend", "rocm7.2"):
        assert flag in cmd
    assert cmd[cmd.index("-o") + 1] == str(txt)
    assert "--upgrade" in cmd
    assert cmd.count("-o") == 1
    assert "requirements.in" in cmd


def test_without_header_falls_back_to_plain_compile(tmp_path: Path) -> None:
    txt = tmp_path / "requirements.txt"
    txt.write_text("foo==1.0\n")
    req_in = tmp_path / "requirements.in"

    assert uv_compile_command(txt, req_in, "-", upgrade=True) == [
        "uv",
        "pip",
        "compile",
        str(req_in),
        "-o",
        "-",
        "--upgrade",
    ]
